package com.fasterxml.jackson.databind.ser;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.io.SerializedString;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonObjectFormatVisitor;
import com.fasterxml.jackson.databind.jsonschema.SchemaAware;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.databind.ser.BeanPropertyWriter;
import com.fasterxml.jackson.databind.ser.PropertySerializerMap;
import com.fasterxml.jackson.databind.ser.impl.PropertySerializerMap;
import com.fasterxml.jackson.databind.ser.impl.UnwrappingBeanPropertyWriter;
import com.fasterxml.jackson.databind.ser.std.StringSerializer;
import com.fasterxml.jackson.databind.util.Annotations;
import com.fasterxml.jackson.databind.util.NameTransformer;
import java.io.*;
import java.lang.annotation.Annotation;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class BeanPropertyWriter_serializeAsColumn_TriageGen1Test {

    private BeanPropertyWriter writer;
    private JsonGenerator jgen;
    private SerializerProvider prov;
    private PropertySerializerMap map;

    // Marker for empty check
    private static final Object MARKER_FOR_EMPTY = new Object();

    @Before
    public void setUp() throws Exception {
        // Since BeanPropertyWriter has protected constructors, we use a subclass or mock
        // But since we need to test the logic of the method itself, we will use spy/mocking
        // Note: BeanPropertyWriter is usually instantiated via BeanSerializerFactory.
        // For unit testing this specific method logic, we'll mock the dependencies.
        writer = mock(BeanPropertyWriter.class, CALLS_REAL_METHODS);
        jgen = mock(JsonGenerator.class);
        prov = mock(SerializerProvider.class);
        map = mock(PropertySerializerMap.class);

        // Injecting private fields via reflection to simulate the internal state
        setInternalField(writer, "_dynamicSerializers", map);
    }

    @Test
    public void testSerializeAsColumn_NullWithNullSerializer() throws Exception {
        Object bean = new Object();
        JsonSerializer<Object> nullSer = mock(JsonSerializer.class);

        doReturn(null).when(writer).get(bean);
        writer.assignNullSerializer(nullSer);

        writer.serializeAsColumn(bean, jgen, prov);

        verify(nullSer).serialize(null, jgen, prov);
        verifyNoMoreInteractions(jgen);
    }

    @Test
    public void testSerializeAsColumn_NullWithoutNullSerializer() throws Exception {
        Object bean = new Object();

        doReturn(null).when(writer).get(bean);
        // Ensure _nullSerializer is null
        setInternalField(writer, "_nullSerializer", null);

        writer.serializeAsColumn(bean, jgen, prov);

        verify(jgen).writeNull();
    }

    @Test
    public void testSerializeAsColumn_WithExistingSerializer() throws Exception {
        Object bean = new Object();
        Object value = "testValue";
        JsonSerializer<Object> ser = mock(JsonSerializer.class);

        doReturn(value).when(writer).get(bean);
        writer.assignSerializer(ser);

        writer.serializeAsColumn(bean, jgen, prov);

        verify(ser).serialize(value, jgen, prov);
    }

    @Test
    public void testSerializeAsColumn_WithDynamicSerializer() throws Exception {
        Object bean = new Object();
        Object value = "testValue";
        JsonSerializer<Object> ser = mock(JsonSerializer.class);

        doReturn(value).when(writer).get(bean);
        setInternalField(writer, "_serializer", null);
        when(map.serializerFor(value.getClass())).thenReturn(ser);

        writer.serializeAsColumn(bean, jgen, prov);

        verify(ser).serialize(value, jgen, prov);
    }

    @Test
    public void testSerializeAsColumn_WithFindAndAddDynamicSerializer() throws Exception {
        Object bean = new Object();
        Object value = "testValue";
        JsonSerializer<Object> ser = mock(JsonSerializer.class);

        doReturn(value).when(writer).get(bean);
        setInternalField(writer, "_serializer", null);
        when(map.serializerFor(value.getClass())).thenReturn(null);
        // Mocking the protected method _findAndAddDynamic
        doReturn(ser).when(writer)._findAndAddDynamic(eq(map), eq(value.getClass()), eq(prov));

        writer.serializeAsColumn(bean, jgen, prov);

        verify(ser).serialize(value, jgen, prov);
    }

    @Test
    public void testSerializeAsColumn_SuppressEmptyValue() throws Exception {
        Object bean = new Object();
        Object value = ""; 
        JsonSerializer<Object> ser = mock(JsonSerializer.class);

        doReturn(value).when(writer).get(bean);
        writer.assignSerializer(ser);
        setInternalField(writer, "_suppressableValue", MARKER_FOR_EMPTY);
        when(ser.isEmpty(value)).thenReturn(true);

        writer.serializeAsColumn(bean, jgen, prov);

        verify(writer).serializeAsPlaceholder(bean, jgen, prov);
        verify(ser, never()).serialize(any(), any(), any());
    }

    @Test
    public void testSerializeAsColumn_SuppressSpecificValue() throws Exception {
        Object bean = new Object();
        Object value = "suppressMe";
        JsonSerializer<Object> ser = mock(JsonSerializer.class);

        doReturn(value).when(writer).get(bean);
        writer.assignSerializer(ser);
        setInternalField(writer, "_suppressableValue", "suppressMe");

        writer.serializeAsColumn(bean, jgen, prov);

        verify(writer).serializeAsPlaceholder(bean, jgen, prov);
    }

    @Test
    public void testSerializeAsColumn_SelfReference() throws Exception {
        Object bean = new Object();
        doReturn(bean).when(writer).get(bean);
        JsonSerializer<Object> ser = mock(JsonSerializer.class);
        writer.assignSerializer(ser);

        writer.serializeAsColumn(bean, jgen, prov);

        verify(writer)._handleSelfReference(bean, ser);
        verify(ser).serialize(bean, jgen, prov);
    }

    @Test
    public void testSerializeAsColumn_WithTypeSerializer() throws Exception {
        Object bean = new Object();
        Object value = "test";
        JsonSerializer<Object> ser = mock(JsonSerializer.class);
        com.fasterxml.jackson.databind.ser.std.TypeSerializer typeSer = mock(com.fasterxml.jackson.databind.ser.std.TypeSerializer.class);

        doReturn(value).when(writer).get(bean);
        writer.assignSerializer(ser);
        setInternalField(writer, "_typeSerializer", typeSer);

        writer.serializeAsColumn(bean, jgen, prov);

        verify(ser).serializeWithType(value, jgen, prov, typeSer);
    }

    @Test
    public void testSerializeAsColumn_NonSuppressedValue() throws Exception {
        Object bean = new Object();
        Object value = "normal";
        JsonSerializer<Object> ser = mock(JsonSerializer.class);

        doReturn(value).when(writer).get(bean);
        writer.assignSerializer(ser);
        setInternalField(writer, "_suppressableValue", "different");

        writer.serializeAsColumn(bean, jgen, prov);

        verify(ser).serialize(value, jgen, prov);
    }

    private void setInternalField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }
}
